describe('Logout from Side Menu', () => {
  beforeEach(() => {
    cy.visit('https://www.saucedemo.com');
    cy.get('[data-test="username"]').type('standard_user');
    cy.get('[data-test="password"]').type('secret_sauce');
    cy.get('[data-test="login-button"]').click();
    cy.get('[data-test="inventory-container"]').should('be.visible');
  });

  it('should successfully logout via side menu and return to login page', () => {
    cy.get('#react-burger-menu-btn').click();
    cy.get('#logout_sidebar_link').should('be.visible');
    cy.get('#logout_sidebar_link').click();
    cy.url().should('eq', 'https://www.saucedemo.com/');
    cy.get('[data-test="login-button"]').should('be.visible');
  });

  it('should display side menu when burger menu button is clicked', () => {
    cy.get('#react-burger-menu-btn').click();
    cy.get('.bm-menu').should('be.visible');
    cy.get('#logout_sidebar_link').should('be.visible');
    cy.get('#inventory_sidebar_link').should('be.visible');
    cy.get('#about_sidebar_link').should('be.visible');
    cy.get('#reset_sidebar_link').should('be.visible');
  });

  it('should handle logout when side menu is already open', () => {
    cy.get('#react-burger-menu-btn').click();
    cy.get('.bm-menu').should('be.visible');
    cy.get('#logout_sidebar_link').click();
    cy.url().should('eq', 'https://www.saucedemo.com/');
    cy.get('[data-test="login-button"]').should('be.visible');
    cy.get('.bm-menu').should('not.be.visible');
  });

  it('should not allow access to inventory after logout', () => {
    cy.get('#react-burger-menu-btn').click();
    cy.get('#logout_sidebar_link').click();
    cy.url().should('eq', 'https://www.saucedemo.com/');
    cy.visit('https://www.saucedemo.com/inventory.html');
    cy.url().should('eq', 'https://www.saucedemo.com/');
    cy.get('[data-test="login-button"]').should('be.visible');
  });
});
